
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_16_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_16", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.116286881797042e+00, -5.015146228220927e+00, -4.873304036549963e+00, -4.676539424128038e+00, -4.407749472019193e+00, -4.048291990663856e+00, -3.580990461343155e+00, -2.994327739858642e+00, -2.287825259798471e+00, -1.513158277964854e+00, -8.927027242563649e-01, -6.424466548838706e-01, -6.289969566566451e-01, -5.398345850460472e-01, -3.660900655546848e-01, -1.984431230542477e-01, -8.628257498550103e-02, -2.846850188326340e-02, -6.102566345532519e-03, -6.862355049523340e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


